VALUES
    ('no_pan_higher_rate', 'it_act_1961', '206AA', 'Higher rate of tax when the deductee''s PAN is not furnished or is invalid (the rate is no_pan_rate of tds_rates).', DATE '2025-04-01', DATE '2026-03-31', 'Recalled / secondary mentions; official text not read', 'pending', 'Section number is the 1961 Act reference as recalled.'),
    ('no_pan_higher_rate', 'it_act_2025', 'to be confirmed (Income-tax Act 2025 section number not verified)', 'Higher rate of tax when the deductee''s PAN is not furnished or is invalid (the rate is no_pan_rate of tds_rates).', DATE '2026-04-01', NULL, 'Income-tax Act 2025 section number not found in a readable source; the rule itself is reported unchanged', 'pending', 'Owner / CA to supply the 2025-Act section number.'),
    ('lower_deduction_certificate', 'it_act_1961', '197', 'Deduction at the lower / nil rate stated in the Assessing Officer''s certificate (Form 13), within its validity and amount limit.', DATE '2025-04-01', DATE '2026-03-31', 'Recalled / secondary mentions; official text not read', 'pending', 'Section number is the 1961 Act reference as recalled.'),
    ('lower_deduction_certificate', 'it_act_2025', 'to be confirmed (Income-tax Act 2025 section number not verified)', 'Deduction at the lower / nil rate stated in the Assessing Officer''s certificate (Form 13), within its validity and amount limit.', DATE '2026-04-01', NULL, 'Income-tax Act 2025 section number not found in a readable source; the rule itself is reported unchanged', 'pending', 'Owner / CA to supply the 2025-Act section number.'),
    ('tcs_no_pan_higher_rate', 'it_act_1961', '206CC', 'Higher rate of tax collected at source when the collectee''s PAN is not furnished.', DATE '2025-04-01', DATE '2026-03-31', 'Recalled / secondary mentions; official text not read', 'pending', 'Section number is the 1961 Act reference as recalled.'),
    ('tcs_no_pan_higher_rate', 'it_act_2025', 'to be confirmed (Income-tax Act 2025 section number not verified)', 'Higher rate of tax collected at source when the collectee''s PAN is not furnished.', DATE '2026-04-01', NULL, 'Income-tax Act 2025 section number not found in a readable source; the rule itself is reported unchanged', 'pending', 'Owner / CA to supply the 2025-Act section number.'),
