    ('rounding_nearest_rupee', 'it_act_1961', '288B', 'Tax payable is rounded to the nearest rupee (tax amounts are whole rupees; engine rule T-06).', DATE '2025-04-01', DATE '2026-03-31', 'Recalled / secondary mentions; official text not read', 'pending', 'Section number is the 1961 Act reference as recalled.'),
    ('rounding_nearest_rupee', 'it_act_2025', 'to be confirmed (Income-tax Act 2025 section number not verified)', 'Tax payable is rounded to the nearest rupee (tax amounts are whole rupees; engine rule T-06).', DATE '2026-04-01', NULL, 'Income-tax Act 2025 section number not found in a readable source; the rule itself is reported unchanged', 'pending', 'Owner / CA to supply the 2025-Act section number.'),
    ('gst_excluded_from_base', 'it_act_1961', 'CBDT Circular 23/2017 (as recalled)', 'Where GST is shown separately in the invoice, tax is deducted on the amount excluding GST (not for GST-inclusive invoices); the engine takes the base the accountant states and warns when GST is shown.', DATE '2025-04-01', DATE '2026-03-31', 'Recalled / secondary mentions; official text not read', 'pending', 'Section number is the 1961 Act reference as recalled.'),
    ('gst_excluded_from_base', 'it_act_2025', 'to be confirmed (Income-tax Act 2025 section number not verified)', 'Where GST is shown separately in the invoice, tax is deducted on the amount excluding GST (not for GST-inclusive invoices); the engine takes the base the accountant states and warns when GST is shown.', DATE '2026-04-01', NULL, 'Income-tax Act 2025 section number not found in a readable source; the rule itself is reported unchanged', 'pending', 'Owner / CA to supply the 2025-Act section number.'),
    ('non_filer_206ab_omitted', 'it_act_1961', '206AB / 206CCA', 'Special higher rate for non-filers of returns was omitted from 1-4-2025 (Finance Act 2025, as recalled): not modelled.', DATE '2025-04-01', DATE '2026-03-31', 'Recalled / secondary mentions; official text not read', 'pending', 'Section number is the 1961 Act reference as recalled.'),
    ('non_filer_206ab_omitted', 'it_act_2025', 'to be confirmed (Income-tax Act 2025 section number not verified)', 'Special higher rate for non-filers of returns was omitted from 1-4-2025 (Finance Act 2025, as recalled): not modelled.', DATE '2026-04-01', NULL, 'Income-tax Act 2025 section number not found in a readable source; the rule itself is reported unchanged', 'pending', 'Owner / CA to supply the 2025-Act section number.'),
    ('threshold_whole_amount_rule', 'it_act_1961', 'CBDT circular on thresholds', 'Where a single-payment / annual threshold is crossed, tax is deducted on the whole amount from the crossing payment (except 194Q and TCS above a limit: the excess only); the part credited before the crossing is brought in at the crossing payment.', DATE '2025-04-01', DATE '2026-03-31', 'Recalled / secondary mentions; official text not read', 'pending', 'Section number is the 1961 Act reference as recalled.'),
    ('threshold_whole_amount_rule', 'it_act_2025', 'to be confirmed (Income-tax Act 2025 section number not verified)', 'Where a single-payment / annual threshold is crossed, tax is deducted on the whole amount from the crossing payment (except 194Q and TCS above a limit: the excess only); the part credited before the crossing is brought in at the crossing payment.', DATE '2026-04-01', NULL, 'Income-tax Act 2025 section number not found in a readable source; the rule itself is reported unchanged', 'pending', 'Owner / CA to supply the 2025-Act section number.')
